<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\TenantConfigAllowRegisterVO;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Holder\TenantConfigAllowRegisterAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigAllowRegisterAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantConfigAllowRegisterAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that isAllowRegister returns null on a freshly created holder.
         */
        public function testAllowRegisterNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithTenantConfigAllowRegisterAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isAllowRegisterAssigned());
            $this->assertNull($holder->isAllowRegister());
        }
}
class ImplWithTenantConfigAllowRegisterAttributeHolderUnitTest
{
  use TenantConfigAllowRegisterAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedAllowRegisterRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultAllowRegister();
    }}
